for i in $(ls *bcf | grep -v "0.1M");do out=$(basename $i | cut -d "." -f 1,2,3,4);/input/tools/plink2 --pfile 03.PCA30/$out --threads 30 --glm hide-covar firth-fallback --covar 03.PCA30/$out.eigenvec --adjust --ci 0.95 --make-pfile --out 04.firthfall/$out 1>04.firthfall/$out.log 2>04.firthfall/$out.err ;done
